CREATE TABLE IF NOT EXISTS slack_coworker_private_status (preview_id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,account_id TEXT NOT NULL,member_json TEXT NOT NULL,draft_id TEXT NOT NULL UNIQUE,handoff_id TEXT NOT NULL UNIQUE,target_json TEXT NOT NULL,installation_json TEXT NOT NULL,source_json TEXT NOT NULL,preview_json TEXT NOT NULL,preview_digest TEXT NOT NULL,state TEXT NOT NULL,delivery_state TEXT NOT NULL,claim_id TEXT,lease_expires_at INTEGER,attempted_json TEXT NOT NULL,last_status TEXT,used_notices INTEGER NOT NULL,next_check_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,error_code TEXT,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS slack_coworker_private_status_due ON slack_coworker_private_status(state,next_check_at);
